Code.Terraform:
```hcl
# Terraform: attach a data protection policy to a CloudWatch log group
resource "aws_cloudwatch_log_data_protection_policy" "<example_resource_name>" {
  log_group_name = aws_cloudwatch_log_group.<example_resource_name>.name

  policy_document = jsonencode({
    Name    = "data-protection-policy"
    Version = "2021-06-01"
    Statement = [
      {
        Sid            = "audit"
        DataIdentifier = ["arn:aws:dataprotection::aws:data-identifier/EmailAddress"]
        Operation      = { Audit = { FindingsDestination = {} } }
      },
      {
        Sid            = "redact"
        DataIdentifier = ["arn:aws:dataprotection::aws:data-identifier/EmailAddress"]
        Operation      = { Deidentify = { MaskConfig = {} } }
      }
    ]
  })
}
```
